use vstd::prelude::*;
use vstd::vec::Vec;

#[derive(Clone, PartialEq, Eq)]
#[verifier(packed)]
pub struct Complex {
    real: i32,
    imag: i32,
}

verus! {
    // fixed machine epsilon
    const EPS: i32 = 2;

    spec fn abs(x: i32) -> i32 {
        if x < 0 { -x } else { x }
    }

    // predicate: is the imaginary part "close" to zero?
    spec fn is_close(c: Complex, tol: i32) -> bool {
        abs(c.imag) <= tol * EPS
    }

    // main function
    fn real_if_close(arr: Vec<Complex>, tol: i32) -> (result: Vec<Complex>)
        requires
            tol > 0,
        ensures
            // length unchanged
            result.len() == arr.len(),
        ensures
            // real parts always preserved
            forall|i: int| 0 <= i && i < arr.len() ==>
                result[i].real == arr[i].real,
        ensures
            // if input was already purely real, we return it verbatim
            (forall|i: int| 0 <= i && i < arr.len() ==>
                arr[i].imag == 0)
            ==> result == arr
    {
        let n = arr.len();

        // first pass: decide whether *all* imaginary parts are within tolerance
        let mut all_close: bool = true;
        let mut i: usize = 0;
        while i < n
            invariant 0 <= i <= n,
            invariant all_close ==>
                forall|j: int| 0 <= j && j < i ==>
                    abs(arr[j].imag) <= tol * EPS,
            decreases n - i
        {
            if abs(arr[i].imag) > tol * EPS {
                all_close = false;
            }
            i = i + 1;
        }

        if all_close {
            // build a new vector of the same length with imag = 0
            let mut res: Vec<Complex> = Vec::empty();
            res = Vec::with_capacity(n);
            let mut k: usize = 0;
            while k < n
                invariant 0 <= k <= n,
                invariant res.len() == k,
                invariant forall|j: int| 0 <= j && j < k ==>
                    res[j].real == arr[j].real && res[j].imag == 0,
                decreases n - k
            {
                let c = arr.get(k);
                res.push(Complex { real: c.real, imag: 0 });
                k = k + 1;
            }
            // prove that if the input was already real, res == arr
            proof {
                // under the assumption ∀i< n. arr[i].imag == 0,
                // we show ∀i. res[i] == arr[i], hence res == arr.
                assert((forall|idx: int| 0 <= idx && idx < n ==>
                    {
                        let a = arr.get(idx as nat);
                        let r = res.get(idx as nat);
                        // both real parts are equal by construction,
                        // and r.imag=0=a.imag, so the Complexes are equal
                        r.real == a.real && r.imag == a.imag
                    }
                ));
            }
            return res;
        } else {
            // some imaginary part was out-of-tolerance: return the input unchanged
            return arr;
        }
    }
}

